mapper.select:
SELECT id, product_name, product_code, price
FROM stock_data
WHERE id = #{id}

mapper.update:
UPDATE stock_data
product_code = #{r.productCode}, product_name = #{r.productName}, specification = #{r.specification}, price = #{r.price}, category = #{r.category}, supplier = #{r.supplier}, applicant = #{r.applicant}, approver = #{r.approver}, system_assign = #{r.systemAssign}, freezer_category = #{r.freezerCategory}, freezer_position = #{r.freezerPosition},
WHERE id = #{id}

mapper.select:
SELECT price FROM stock_data
WHERE price IS NOT NULL AND price > 0

    AND product_code = #{codeNumber}

AND product_name = #{productName}
ORDER BY updated_at DESC, id DESC
LIMIT 1
